net.coobird.thumbnailator.builders.ThumbnailParameterBuilder builder1 = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder();
builder1.scale(0.75);
net.coobird.thumbnailator.ThumbnailParameter param1 = builder1.build();
double scale1 = param1.getHeightScalingFactor();

net.coobird.thumbnailator.builders.ThumbnailParameterBuilder builder2 = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder();
builder2.size(100, 100);
net.coobird.thumbnailator.ThumbnailParameter param2 = builder2.build();
double scale2 = param2.getHeightScalingFactor();

assert scale1 == 0.75 : "Expected height scaling factor to be 0.75, got " + scale1;
assert Double.isNaN(scale2) : "Expected height scaling factor to be NaN when size is set, got " + scale2;

System.out.println("__CHECK__ getHeightScalingFactor " + scale1 + ", " + scale2);

